    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">xB̂y</span> و <span dir=\"ltr\" class=\"expr pt\">AB̂x</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">xB̂y = 52°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[Bt)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xB̂y</span>  و  <span dir=\"ltr\" class=\"expr pt\">[Bu)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂x</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">tB̂u.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [Bt)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xB̂y</span>  و  <span dir=\"ltr\" class=\"expr pt\">xB̂y = 52°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[Bt)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xB̂y</span>  و  <span dir=\"ltr\" class=\"expr pt\">xB̂y = 52°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">tB̂x = 52° : 2 = 26°</span>"},{"quoi":"القاعدة","math":"زاويتان متكاملتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">xB̂y</span> و <span dir=\"ltr\" class=\"expr pt\">AB̂x</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">xB̂y = 52°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AB̂x = 180° - 52° = 128°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[Bu)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂x</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂x = 128°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">uB̂x = 128° : 2 = 64°</span>"},{"quoi":"القاعدة","math":"إذا كانت زاويتان متجاورتين فإنّ قيس الزاوية الكبرى يساوي مجموع قيسيهما"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">tB̂x</span> و <span dir=\"ltr\" class=\"expr pt\">uB̂x</span> متجاورتان  و  <span dir=\"ltr\" class=\"expr pt\">tB̂x = 26°</span>  و  <span dir=\"ltr\" class=\"expr pt\">uB̂x = 64°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">tB̂u = 26° + 64° = 90°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">tB̂u = 90°</span>"}],
