    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 116°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 53°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB.</span> نختار مجموع زوايا المثلّث لأنّ معطياتها متوفّرة : في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 116°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 53°.</span> و لماذا لا المنصّف ؟ لأنّها تحتاج منصّفا، و لا منصّف في الشّكل."},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 116°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 53°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (116° + 53°) = 11°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AĈB = 11°</span>"}],
