    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 56°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">BÔC.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 56°.</span> و لماذا لا الزاويتان المتقابلتان بالرأس ؟ لأنّها تحتاج زاويتين متقابلتين بالرأس، و لا وجود لهما هنا."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 56°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 56° : 2 = 28°</span>"},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 56°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 56°) = 34°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈB = 34°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BĈO = 34° : 2 = 17°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">OBC</span>  و  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 28°</span>  و  <span dir=\"ltr\" class=\"expr pt\">BĈO = 17°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BÔC = 180° - (28° + 17°) = 135°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BÔC = 135°</span>"}],
